GRANT SELECT ON public.media TO anon;
CREATE POLICY approved_media_public ON public.media FOR SELECT TO anon,authenticated USING(approved AND (EXISTS(SELECT 1 FROM public.content c WHERE c.image_id=media.id AND c.published) OR EXISTS(SELECT 1 FROM public.website_settings s WHERE s.logo_id=media.id)));
CREATE FUNCTION public.move_content(_id uuid,_direction integer) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE target public.content; neighbor public.content; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _direction NOT IN (-1,1) THEN RAISE EXCEPTION 'Invalid direction'; END IF; PERFORM pg_advisory_xact_lock(731948); SELECT * INTO target FROM public.content WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Missing item'; END IF; WITH ordered AS (SELECT id,row_number() OVER(ORDER BY display_order,created_at,id)::integer AS position FROM public.content WHERE kind=target.kind) UPDATE public.content c SET display_order=ordered.position FROM ordered WHERE c.id=ordered.id; SELECT * INTO target FROM public.content WHERE id=_id; SELECT * INTO neighbor FROM public.content WHERE kind=target.kind AND display_order=target.display_order+_direction; IF FOUND THEN UPDATE public.content SET display_order=CASE WHEN id=target.id THEN neighbor.display_order ELSE target.display_order END WHERE id IN(target.id,neighbor.id); END IF; END $$;
REVOKE ALL ON FUNCTION public.move_content(uuid,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.move_content(uuid,integer) TO authenticated;